// A request becomes confirmed content before it becomes a campaign.
const brief={text:'',file:'',reference:'',photo:'',phase:'input',tone:'clean',emphasis:'title',material:'none',type:'promotion',selected:0,confirmed:false,error:'',data:{name:'',title:'',service:'',desc:'',amount:'',period:'',coupon:'',note:'',followup:'',cta:'',cards:[]}};
const briefExamples=[{label:'택시 서비스 오픈',text:'한패스 택시 신규 서비스 오픈을 알리고 싶어요.\n오픈 기념 할인 쿠폰 사용을 유도하고 싶습니다.\n밝고 경쾌한 분위기로 만들어 주세요.'},{label:'송금 서비스 소개',text:'해외 생활비 송금 서비스를 소개하고 싶어요.\n주요 이용 방법을 쉽게 알리고 싶습니다.\n신뢰감 있고 깔끔한 디자인을 원해요.'},{label:'서비스 점검 안내',text:'교통카드 충전 서비스 점검을 안내하고 싶어요.\n중단 일정과 점검 완료 후 안내를 정확하게 전달해야 합니다.'}];
function briefSteps(n){return `<div class="brief-steps">${['요청 내용','정보 확인','시안 선택'].map((t,i)=>`<span class="${i===n?'current':i<n?'complete':''}"><b>${i<n?'✓':i+1}</b>${t}</span>`).join('<i>—</i>')}</div>`}
function briefInput(){return `<div class="brief-page">${briefSteps(0)}<button class="ghost back" data-brief-back="home">← 사용할 곳 다시 선택</button><div class="easy-heading"><h1>어떤 디자인이 필요한가요?</h1><p>동료에게 요청하듯 적어 주세요. 디자인 용어는 몰라도 괜찮아요.</p></div><div class="brief-grid"><section class="card"><div class="row between"><h2>만들고 싶은 내용</h2><span class="badge blue">${kinds[easy.kind][0]}</span></div><label class="field sectionspace">요청 내용 *<textarea id="requestText" placeholder="무엇을 홍보하거나 안내하나요? 누구에게, 어떤 내용을 가장 알리고 싶은지 적어 주세요.">${esc(brief.text)}</textarea></label><div class="brief-examples"><span>예시로 시작하기</span>${briefExamples.map((x,i)=>`<button class="small" data-brief-example="${i}">${x.label}</button>`).join('')}</div><div class="sectionline"></div><h3>기획안이 있나요? <small>선택</small></h3><label class="brief-upload">＋ 기획안 첨부<input id="briefFile" type="file" accept=".txt,.md,.ppt,.pptx,.pdf,.doc,.docx"></label>${brief.file?`<div class="brief-file">▤ ${esc(brief.file)} <button class="small ghost" id="removeBriefFile">제거</button></div>`:''}<p class="footnote">TXT·MD는 내용을 읽어 요청란에 넣습니다. PPT·PDF·Word는 첨부 표시만 가능하며, 내용 분석은 연결되지 않았어요.</p><div class="placement sectionspace"><b>노출 위치</b><div class="row">${kinds[easy.kind][3].map(i=>`<button data-brief-place="${i}" class="${easy.placement===i?'active':''}">${sizes[i].name}<small>${sizes[i].w}×${sizes[i].h}${sizes[i].example?' · 예시':''}</small></button>`).join('')}</div></div>${brief.error?`<div class="errornote" role="alert">${esc(brief.error)}</div>`:''}<button class="primary" id="organizeBrief" style="width:100%">핵심 정보 확인하기 →</button></section><aside class="brief-guide"><span class="kind-icon">${icon('review')}</span><h2>내용은 내가,<br>구성은 스튜디오가</h2><p>요청 내용을 정리하고<br>내 내용이 들어간 시안을 비교해요.</p><ol><li>꼭 전할 내용을 알려 주세요</li><li>금액·기간·조건을 확인하세요</li><li>마음에 드는 시안을 고르세요</li></ol><div class="callout">데모 안내<br>현재는 간단한 규칙으로 정보를 정리하고 승인된 구도에 배치합니다. AI 분석·이미지 생성은 연결되지 않았어요.</div></aside></div></div>`}
function briefField(k,n,multi=false){return `<label class="field">${n}${multi?`<textarea data-brief-field="${k}">${esc(brief.data[k])}</textarea>`:`<input data-brief-field="${k}" value="${esc(brief.data[k])}">`}</label>`}
function briefConfirm(){return `<div class="brief-page">${briefSteps(1)}<button class="ghost back" data-brief-back="brief">← 요청 내용 수정</button><div class="easy-heading"><h1>디자인에 들어갈 내용을 확인해 주세요</h1><p>빈 항목은 직접 입력해 주세요. 금액·일정·조건을 임의로 채우지 않아요.</p></div><div class="brief-grid"><section class="card"><div class="callout">정보 정리 · 데모 초안입니다. 요청 원문과 비교한 후 확정하세요.</div><details class="sectionspace"><summary>내가 입력한 요청 보기</summary><p class="brief-original">${esc(brief.text)}</p></details><div class="type-choices">${Object.entries(designSets).map(([id,t])=>`<button data-brief-type="${id}" class="${brief.type===id?'active':''}">${t.name}</button>`).join('')}</div>${briefField('name','작업 이름 *')}${briefField('service','서비스·상품 이름')}${briefField('title','가장 크게 보여줄 문구 *',true)}${briefField('desc',brief.type==='notice'?'점검 사유·안내 내용':'설명·참여 조건',true)}${brief.type==='promotion'?`<div class="grid2">${briefField('amount','혜택 금액 (선택)')}${briefField('coupon','쿠폰번호 (선택)')}</div>`:''}${brief.type!=='education'?briefField('period',brief.type==='notice'?'중단·변경 일정 (직접 확인)':'행사 기간 (직접 확인)'):''}${brief.type==='notice'?briefField('followup','후속 안내'):''}${briefField('cta','고객이 하길 원하는 행동 (선택)')}${briefField('note','필수 안내·유의사항 (선택)',true)}<label class="checkfilter"><input type="checkbox" id="confirmBrief" ${brief.confirmed?'checked':''}> 문구와 금액·기간·조건을 확인했어요.</label>${brief.error?`<p class="errornote" role="alert">${esc(brief.error)}</p>`:''}</section><aside class="card brief-options"><h2>어떤 느낌으로 만들까요?</h2><h3 class="sectionspace">강조할 내용</h3><div class="brief-options-list">${[['title','주요 소식','제목을 먼저 보여줘요'],['benefit','혜택·핵심 정보','금액이나 중요한 정보를 강조해요'],['image','이미지','사진을 중심으로 구성해요']].map(([v,n,d])=>`<button data-emphasis="${v}" class="${brief.emphasis===v?'active':''}"><b>${n}</b><small>${d}</small></button>`).join('')}</div><h3 class="sectionspace">분위기</h3><div class="chips">${[['clean','깔끔하게'],['bright','밝고 경쾌하게'],['calm','차분하게']].map(([v,n])=>`<button data-tone="${v}" class="small ${brief.tone===v?'active':''}">${n}</button>`).join('')}</div><h3 class="sectionspace">사용할 이미지</h3><label class="field"><select id="briefMaterial"><option value="none" ${brief.material==='none'?'selected':''}>이미지 없이 문구 중심으로</option><option value="upload" ${brief.material==='upload'?'selected':''}>내 이미지 사용</option></select></label>${brief.material==='upload'?`<label class="brief-upload">사진·일러스트 올리기<input type="file" id="briefPhoto" accept="image/*"></label>${brief.photo?`<img class="brief-photo" src="${brief.photo}" alt="선택한 제작 소재">`:'<small>디자인에 사용할 이미지 파일을 선택하세요.</small>'}`:''}<details class="sectionspace"><summary>참고 디자인 첨부 · 선택</summary><input type="file" id="briefRef" accept="image/*"><p class="footnote">${brief.reference?esc(brief.reference)+' · 첨부됨':'분위기 참고용이며 디자인에 그대로 넣지 않습니다. 자동 분석은 데모 범위 밖입니다.'}</p></details><button id="recommended" class="ghost sectionspace">잘 모르겠어요 · 추천 설정</button><button class="primary" id="buildConcepts" style="width:100%;margin-top:15px">내 내용으로 시안 3개 보기 →</button></aside></div></div>`}
function draftCampaign(variant=0){return {name:brief.data.name,contentType:brief.type,data:structuredClone({...brief.data,noticeMode:'서비스 안내',short:brief.data.title,cards:brief.type==='education'?[{title:brief.data.title,desc:brief.data.desc,art:''},{title:'추가로 알릴 내용',desc:'편집 화면에서 내용을 입력해 주세요.',art:''}]:[]}),briefMade:true,tone:brief.tone,material:brief.material,asset:brief.material==='upload'?brief.photo:'',look:variant,sizeIds:[easy.placement]}}
function briefArt(c,variant=0){const d=c.data,photo=c.material==='upload'&&c.asset;return `<div class="request-art ${sizes[c.sizeIds?.[0]??3].w/sizes[c.sizeIds?.[0]??3].h>1.7?'request-wide':''} tone-${c.tone||'clean'} concept-${variant}" style="--draft-ratio:${sizes[c.sizeIds?.[0]??3].w}/${sizes[c.sizeIds?.[0]??3].h}"><header><b>hanpass</b><small>DEMO</small></header><div class="request-copy"><span>${esc(d.service||designSets[c.contentType].name)}</span><h2 class="btitle">${esc(d.title)}</h2><p>${esc(d.desc)}</p></div>${photo?`<img class="request-image" src="${c.asset}" alt="사용자가 선택한 디자인 소재">`:''}${d.amount||d.coupon||d.followup?`<div class="request-benefit">${d.amount?`<strong>${esc(d.amount)}<small>원</small></strong>`:''}${d.coupon?`<span>쿠폰번호 <b>${esc(d.coupon)}</b></span>`:''}${d.followup?`<p>${esc(d.followup)}</p>`:''}</div>`:''}${c.contentType==='education'&&d.cards?.length?`<div class="request-cards">${d.cards.map((card,i)=>`<div><b>${String(i+1).padStart(2,'0')} ${esc(card.title)}</b><p>${esc(card.desc)}</p>${card.image?`<img src="${card.image}" alt="카드 이미지">`:''}</div>`).join('')}</div>`:''}<div class="request-bottom">${d.period?`<p>${esc(d.period)}</p>`:''}${d.cta?`<span class="request-cta">${esc(d.cta)} →</span>`:''}</div><footer>${esc(d.note||'미리보기 · 게시 전 검수 필요')}</footer></div>`}
function conceptNames(){return brief.emphasis==='image'?['이미지와 문구 균형','메시지 먼저','이미지 중심']:brief.emphasis==='benefit'?['핵심 정보 정리','혜택 크게','간결한 안내']:['제목 먼저','핵심 정보 강조','내용 나누어 전달']}
function conceptsPage(){return `<div class="brief-page brief-wide">${briefSteps(2)}<button class="ghost back" data-brief-back="brief-confirm">← 내용·분위기 수정</button><div class="easy-heading"><h1>어떤 시안이 마음에 드나요?</h1><p>입력한 내용은 같고, 강조 방식과 배치가 달라요.</p></div><div class="callout">${esc(brief.data.name)} · ${sizes[easy.placement].name} · ${sizes[easy.placement].w}×${sizes[easy.placement].h} ${sizes[easy.placement].example?'(예시 규격)':''}<span class="grow"></span><small>자동 생성 AI 미연결 · 배치 데모</small></div><div class="concept-grid">${conceptNames().map((n,i)=>`<button class="concept-card ${brief.selected===i?'selected':''}" data-concept="${i}"><div class="concept-view">${briefArt(draftCampaign(i),i)}</div><div class="choice-caption"><h3>${n}</h3><span class="radio-mark">${brief.selected===i?'✓':''}</span></div></button>`).join('')}</div><div class="choice-footer"><small>다음 화면에서 문구와 사진을 더 수정할 수 있어요.</small><button class="primary" id="acceptConcept">이 시안으로 편집하기 →</button></div></div>`}
function organizeRequest(){const text=brief.text.trim();if(text.length<8){brief.error='만들고 싶은 내용을 8자 이상 적어 주세요.';render();return}brief.type=/점검|중단|공지/.test(text)?'notice':/교육|예방|이용 방법/.test(text)?'education':'promotion';const first=text.split(/\n/)[0].replace(/(을|를)?\s*(알리고 싶어요|홍보하고 싶어요|안내하고 싶어요|소개하고 싶어요)[.!]?$/,'').trim();brief.data={...brief.data,name:first.slice(0,45),title:first.slice(0,80),desc:text.split('\n').slice(1).join('\n'),service:'',amount:'',period:'',coupon:'',note:'',followup:'',cta:'',cards:[]};brief.confirmed=false;brief.error='';navigate('brief-confirm')}
const beforeBriefBanner=banner;banner=function(){if(!camp().briefMade)return beforeBriefBanner();return briefArt({...camp(),data:data(),asset:state.asset||camp().asset,sizeIds:[state.size]},camp().look||0)};
const beforeBriefArt=easyArt;easyArt=function(c,look=0){return c?.briefMade?briefArt(c,look):beforeBriefArt(c,look)};
const beforeBriefSelect=selectWork;selectWork=function(c){beforeBriefSelect(c);if(c.briefMade){state.asset=c.asset||'';render()}};
const beforeBriefCreate=createEasy;createEasy=function(copy){if(!copy?.briefMade)return beforeBriefCreate(copy);const c={...structuredClone(copy),name:copy.name+' (복사)',status:'작업 중',workflow:null};campaigns.push(c);selectWork(c)};
const beforeBriefNavigate=navigate;navigate=function(p){if(!easy.admin&&p==='choose'&&!easy.editing&&!easy.sizeFirst)p='brief';beforeBriefNavigate(p)};
const beforeBriefRender=render;render=function(){const views={'brief':briefInput,'brief-confirm':briefConfirm,'concepts':conceptsPage};if(!easy.admin&&views[state.page]){$('#app').innerHTML=easyShell(views[state.page]());bindBrief();return}beforeBriefRender();if(!easy.admin){$$('[data-kind]').forEach(b=>b.onclick=()=>{easy.kind=+b.dataset.kind;easy.placement=kinds[easy.kind][3][0];easy.editing=false;navigate('brief')});if(camp().briefMade&&state.page==='simple'){if($('#changeLook'))$('#changeLook').onclick=()=>{brief.type=camp().contentType;brief.data=structuredClone(camp().data);brief.tone=camp().tone;brief.material=camp().material;brief.photo=state.asset||camp().asset;brief.confirmed=true;brief.selected=camp().look||0;easy.placement=state.size;navigate('concepts')};if($('#easyFile')){const old=$('#easyFile').onchange;$('#easyFile').onchange=e=>{old(e);camp().asset=state.asset;camp().material='upload';render()}}}}};
function bindBrief(){$$('[data-easy-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.easyNav));$('#enterAdmin').onclick=enterAdmin;$$('[data-brief-back]').forEach(b=>b.onclick=()=>navigate(b.dataset.briefBack));const on=(id,fn,type='onclick')=>{if($('#'+id))$('#'+id)[type]=fn};on('requestText',e=>{brief.text=e.target.value;brief.error=''},'oninput');$$('[data-brief-example]').forEach(b=>b.onclick=()=>{brief.text=briefExamples[+b.dataset.briefExample].text;brief.error='';render()});$$('[data-brief-place]').forEach(b=>b.onclick=()=>{easy.placement=+b.dataset.briefPlace;render()});on('briefFile',async e=>{const f=e.target.files[0];if(!f)return;brief.file=f.name;if(/\.(txt|md)$/i.test(f.name)){if(f.size>250000){brief.error='텍스트 기획안은 250KB 이하로 첨부해 주세요.';render();return}brief.text=await f.text()}render()},'onchange');on('removeBriefFile',()=>{brief.file='';render()});on('organizeBrief',organizeRequest);$$('[data-brief-field]').forEach(e=>e.oninput=()=>{brief.data[e.dataset.briefField]=e.value;brief.confirmed=false;if($('#confirmBrief'))$('#confirmBrief').checked=false});$$('[data-brief-type]').forEach(b=>b.onclick=()=>{brief.type=b.dataset.briefType;brief.confirmed=false;render()});$$('[data-tone]').forEach(b=>b.onclick=()=>{brief.tone=b.dataset.tone;render()});$$('[data-emphasis]').forEach(b=>b.onclick=()=>{brief.emphasis=b.dataset.emphasis;render()});on('confirmBrief',e=>brief.confirmed=e.target.checked,'onchange');on('briefMaterial',e=>{brief.material=e.target.value;render()},'onchange');on('briefPhoto',e=>{const f=e.target.files[0];if(f?.type.startsWith('image/')){brief.photo=URL.createObjectURL(f);render()}},'onchange');on('briefRef',e=>{brief.reference=e.target.files[0]?.name||'';render()},'onchange');on('recommended',()=>{brief.emphasis=brief.data.amount?'benefit':'title';brief.tone=brief.type==='notice'?'calm':'clean';render();notify('내용에 맞는 기본 설정을 적용했어요.')});on('buildConcepts',()=>{if(!brief.data.name.trim()||!brief.data.title.trim())brief.error='작업 이름과 메인 문구를 입력해 주세요.';else if(!brief.confirmed)brief.error='입력한 정보를 확인한 뒤 확인 항목을 체크해 주세요.';else if(brief.material==='upload'&&!brief.photo)brief.error='사용할 이미지를 올리거나 이미지 없이 진행을 선택해 주세요.';else{brief.error='';brief.selected=brief.emphasis==='benefit'?1:brief.emphasis==='image'?2:0;navigate('concepts');return}render()});$$('[data-concept]').forEach(b=>b.onclick=()=>{brief.selected=+b.dataset.concept;render()});on('acceptConcept',()=>{const c={...draftCampaign(brief.selected),owner:'김민지',date:'2026-09-30',status:'작업 중',langs:1,sizes:1,languageIds:[0],requestText:brief.text,requestFile:brief.file};campaigns.push(c);selectWork(c);notify('입력한 내용으로 새 작업을 만들었어요. 현재 세션에 저장됩니다.')})}
render();
